pub fn nk_is_inline(kind: i32) -> i32 {
    // 1 for the kinds that live inside a block's text: text, span, link,
    // ref, linebreak, initial (SPEC 3.2). A `break` is a milestone, not an
    // inline. A `field` is either; see `node-is-inline`.
    if kind == nk_text() {
        return 1;
    }
    if kind == nk_span() {
        return 1;
    }
    if kind == nk_link() {
        return 1;
    }
    if kind == nk_ref() {
        return 1;
    }
    if kind == nk_linebreak() {
        return 1;
    }
    if kind == nk_initial() {
        return 1;
    }
    return 0;
}
pub fn node_is_inline(nodes: &mut crate::port::Cells, n: i32) -> i32 {
    // 1 when node n is an inline: an inline KIND, or a `break` with an inline neighbour (D134). A page
    // milestone INSIDE a paragraph (text, break, text) is an inline -- written in `inlines`, in order,
    // with no `id` -- and BETWEEN two blocks it is a block, as `nk-is-inline` of its kind says. A `field`
    // is the same: an inline when it has an inline neighbour or its parent is a paragraph, heading or
    // caption (a form field sits in the block that holds its label, P11.x3, D548); a block among blocks
    // otherwise (SPEC 3.2, as it always was).
    let kind: i32 = nget(nodes, n, 0);
    let pv: i32 = nget(nodes, n, 5);
    let nx: i32 = nget(nodes, n, 4);
    let par: i32 = nget(nodes, n, 1);
    if nk_is_inline(kind) == 1 {
        return 1;
    }
    if kind == nk_field() {
        if pv >= 0 {
            let pkind: i32 = nget(nodes, pv, 0);
            if nk_is_inline(pkind) == 1 {
                return 1;
            }
        }
        if nx >= 0 {
            let nkind: i32 = nget(nodes, nx, 0);
            if nk_is_inline(nkind) == 1 {
                return 1;
            }
        }
        if par >= 0 {
            let qkind: i32 = nget(nodes, par, 0);
            if (qkind == nk_paragraph()) || (qkind == nk_heading()) || (qkind == nk_caption()) {
                return 1;
            }
        }
    }
    if kind == nk_break() {
        if pv >= 0 {
            let pkind: i32 = nget(nodes, pv, 0);
            if nk_is_inline(pkind) == 1 {
                return 1;
            }
        }
        if nx >= 0 {
            let nkind: i32 = nget(nodes, nx, 0);
            if nk_is_inline(nkind) == 1 {
                return 1;
            }
        }
    }
    return 0;
}
pub fn node_child_count(nodes: &mut crate::port::Cells, n: i32) -> i32 {
    let mut c: i32 = nget(nodes, n, 2);
    let mut k: i32 = 0;
    while c >= 0 {
        k += 1;
        c = nget(nodes, c, 4);
    }
    return k;
}
pub fn node_depth(nodes: &mut crate::port::Cells, n: i32) -> i32 {
    // Edges from the node to its root: the root is 0.
    let mut p: i32 = nget(nodes, n, 1);
    let mut d: i32 = 0;
    while p >= 0 {
        d += 1;
        p = nget(nodes, p, 1);
    }
    return d;
}
pub fn node_new(mut nodes: &mut crate::port::Cells, kind: i32, parent: i32) -> i32 {
    // Append a node as the LAST child of `parent` (-1: a new root) and
    // answer its index, or -1 when `parent` is not a node, the kind is
    // unknown, or the node would nest deeper than `max-depth`. A new
    // node has no text, no regions, no attributes, `src` 0, `conf` -1
    // (absent), `flags` 0, `sub` 0, `aux` 0.
    let n: i32 = crate::port::cells_len(nodes) / 16;
    let mut last: i32 = -1;
    if (kind < 1) || (kind > 26) {
        return -1;
    }
    if parent < -1 {
        return -1;
    }
    if parent >= n {
        return -1;
    }
    if parent >= 0 {
        if node_depth(nodes, parent) >= (max_depth() - 1) {
            return -1;
        }
        last = nget(nodes, parent, 3);
    }
    crate::port::cells_push(nodes, kind);
    crate::port::cells_push(nodes, parent);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, last);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, 0);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, 0);
    crate::port::cells_push(nodes, 0);
    crate::port::cells_push(nodes, -1);
    crate::port::cells_push(nodes, 0);
    crate::port::cells_push(nodes, 0);
    crate::port::cells_push(nodes, 0);
    if parent >= 0 {
        if last < 0 {
            nput(nodes, parent, 2, n);
        } else {
            nput(nodes, last, 4, n);
        }
        nput(nodes, parent, 3, n);
    }
    return n;
}
pub fn model_init(mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut regions: &mut crate::port::Cells, mut text: &mut crate::port::Cells, mut pages: &mut crate::port::Cells, mut ledger: &mut crate::port::Cells, mut layout: &mut crate::port::Cells) -> i32 {
    // Empty all seven arenas and create the `document` root, node 0.
    crate::port::cells_drop(nodes, 0);
    crate::port::cells_drop(attrs, 0);
    crate::port::cells_drop(regions, 0);
    crate::port::cells_drop(text, 0);
    crate::port::cells_drop(pages, 0);
    crate::port::cells_drop(ledger, 0);
    crate::port::cells_drop(layout, 0);
    node_new(nodes, nk_document(), -1);
    return 0;
}
pub fn node_set_text(mut nodes: &mut crate::port::Cells, n: i32, start: i32, ln: i32) -> i32 {
    // The node's own text is the run [start, start+length) of the text arena.
    nput(nodes, n, 7, start);
    nput(nodes, n, 8, ln);
    return 0;
}
