pub fn node_set_conf(mut nodes: &mut crate::port::Cells, n: i32, v: i32) -> i32 {
    // 0..1000, or -1 for absent. Anything else is clamped to that range.
    if v < -1 {
        return nput(nodes, n, 12, -1);
    }
    if v > 1000 {
        return nput(nodes, n, 12, 1000);
    }
    return nput(nodes, n, 12, v);
}
