pub fn ledger_add(mut ledger: &mut crate::port::Cells, reason: i32, page: i32, x0: i32, y0: i32, x1: i32, y1: i32, conf: i32, src: i32) -> i32 {
    // Append a ledger row (no text yet) and answer its index.
    let l: i32 = crate::port::cells_len(ledger) / 10;
    crate::port::cells_push(ledger, reason);
    crate::port::cells_push(ledger, page);
    crate::port::cells_push(ledger, x0);
    crate::port::cells_push(ledger, y0);
    crate::port::cells_push(ledger, x1);
    crate::port::cells_push(ledger, y1);
    crate::port::cells_push(ledger, -1);
    crate::port::cells_push(ledger, 0);
    crate::port::cells_push(ledger, conf);
    crate::port::cells_push(ledger, src);
    return l;
}
