pub(crate) fn mc_fail(mut st: &mut crate::port::Cells, code: i32, at: i32) -> i32 {
    crate::port::cells_set(st, 0, at);
    return code;
}
pub(crate) fn mc_link_ok(v: i32, n: i32) -> i32 {
    // 1 when v is -1 or an index below n.
    if v < -1 {
        return 0;
    }
    if v >= n {
        return 0;
    }
    return 1;
}
pub(crate) fn mc_run_ok(start: i32, ln: i32, tl: i32) -> i32 {
    // 1 for an absent run (start -1, ln 0) or one inside [0, tl).
    if start == -1 {
        if ln == 0 {
            return 1;
        }
        return 0;
    }
    if start < 0 {
        return 0;
    }
    if ln < 0 {
        return 0;
    }
    if start > tl {
        return 0;
    }
    if ln > (tl - start) {
        return 0;
    }
    return 1;
}
pub(crate) fn mc_check_node(nodes: &mut crate::port::Cells, attrs: &mut crate::port::Cells, regions: &mut crate::port::Cells, text: &mut crate::port::Cells, n: i32, nn: i32) -> i32 {
    // One node's own fields. 0 or an `mc` code.
    let kind: i32 = nget(nodes, n, 0);
    let cnt: i32 = nget(nodes, n, 10);
    let conf: i32 = nget(nodes, n, 12);
    let mut a: i32 = nget(nodes, n, 6);
    let mut r: i32 = nget(nodes, n, 9);
    let mut steps: i32 = 0;
    let na: i32 = crate::port::cells_len(attrs) / 5;
    let nr: i32 = crate::port::cells_len(regions) / 6;
    let tl: i32 = crate::port::cells_len(text);
    if (kind < 1) || (kind > 26) {
        return mc_bad_kind();
    }
    if mc_link_ok(nget(nodes, n, 1), nn) == 0 {
        return mc_bad_link();
    }
    if mc_link_ok(nget(nodes, n, 2), nn) == 0 {
        return mc_bad_link();
    }
    if mc_link_ok(nget(nodes, n, 3), nn) == 0 {
        return mc_bad_link();
    }
    if mc_link_ok(nget(nodes, n, 4), nn) == 0 {
        return mc_bad_link();
    }
    if mc_link_ok(nget(nodes, n, 5), nn) == 0 {
        return mc_bad_link();
    }
    if mc_run_ok(nget(nodes, n, 7), nget(nodes, n, 8), tl) == 0 {
        return mc_bad_text();
    }
    if (conf < -1) || (conf > 1000) {
        return mc_bad_conf();
    }
    while a >= 0 {
        if a >= na {
            return mc_bad_attr();
        }
        if steps > na {
            return mc_bad_attr();
        }
        steps += 1;
        if aget(attrs, a, 1) == 1 {
            if mc_run_ok(aget(attrs, a, 2), aget(attrs, a, 3), tl) == 0 {
                return mc_bad_attr();
            }
        }
        if mc_link_ok(aget(attrs, a, 4), na) == 0 {
            return mc_bad_attr();
        }
        if (aget(attrs, a, 1) < 0) || (aget(attrs, a, 1) > 3) {
            return mc_bad_attr();
        }
        a = aget(attrs, a, 4);
    }
    steps = 0;
    while r >= 0 {
        if r >= nr {
            return mc_bad_region();
        }
        if steps > nr {
            return mc_bad_region();
        }
        steps += 1;
        if mc_link_ok(rget(regions, r, 5), nr) == 0 {
            return mc_bad_region();
        }
        r = rget(regions, r, 5);
    }
    if steps != cnt {
        return mc_bad_region();
    }
    return 0;
}
pub(crate) fn mc_check_children(nodes: &mut crate::port::Cells, n: i32, nn: i32) -> i32 {
    // The child chain of n: every child points back at n, prev links
    // agree, `last-child` is the end of the chain. Answers the number of
    // children, or -1 when the chain is wrong.
    let mut c: i32 = nget(nodes, n, 2);
    let mut prev: i32 = -1;
    let mut k: i32 = 0;
    while c >= 0 {
        if k > nn {
            return -1;
        }
        if nget(nodes, c, 1) != n {
            return -1;
        }
        if nget(nodes, c, 5) != prev {
            return -1;
        }
        k += 1;
        prev = c;
        c = nget(nodes, c, 4);
    }
    if nget(nodes, n, 3) != prev {
        return -1;
    }
    return k;
}
pub(crate) fn mc_check_order(nodes: &mut crate::port::Cells, nn: i32, mut st: &mut crate::port::Cells) -> i32 {
    // Pre-order ids: walking each tree in pre-order, from its root,
    // visits the indices consecutively, and the trees follow each other
    // in index order. So an id is the node's position in document
    // order (SPEC 3.3).
    let mut i: i32 = 0;
    let mut expect: i32 = 0;
    let mut cur: i32 = 0;
    while i < nn {
        if nget(nodes, i, 1) == -1 {
            if i != expect {
                return mc_fail(st, mc_not_preorder(), i);
            }
            cur = i;
            while cur >= 0 {
                if cur != expect {
                    return mc_fail(st, mc_not_preorder(), cur);
                }
                expect += 1;
                if nget(nodes, cur, 2) >= 0 {
                    cur = nget(nodes, cur, 2);
                } else {
                    while (cur >= 0) && (cur != i) && (nget(nodes, cur, 4) < 0) {
                        cur = nget(nodes, cur, 1);
                    }
                    if cur == i {
                        cur = -1;
                    } else if cur >= 0 {
                        cur = nget(nodes, cur, 4);
                    }
                }
            }
        }
        i += 1;
    }
    if expect != nn {
        return mc_fail(st, mc_not_preorder(), expect);
    }
    return 0;
}
pub fn model_check(nodes: &mut crate::port::Cells, attrs: &mut crate::port::Cells, regions: &mut crate::port::Cells, text: &mut crate::port::Cells, pages: &mut crate::port::Cells, ledger: &mut crate::port::Cells, layout: &mut crate::port::Cells, mut st: &mut crate::port::Cells) -> i32 {
    let nn: i32 = crate::port::cells_len(nodes) / 16;
    let nlay: i32 = crate::port::cells_len(layout) / 8;
    let mut j: i32 = 0;
    let mut i: i32 = 0;
    let mut rc: i32 = 0;
    let mut kids: i32 = 0;
    let mut total: i32 = 0;
    let mut nonroot: i32 = 0;
    let tl: i32 = crate::port::cells_len(text);
    crate::port::cells_drop(st, 0);
    crate::port::cells_push(st, 0);
    if (crate::port::cells_len(nodes) % 16) != 0 {
        return mc_fail(st, mc_bad_stride(), 0);
    }
    if (crate::port::cells_len(attrs) % 5) != 0 {
        return mc_fail(st, mc_bad_stride(), 0);
    }
    if (crate::port::cells_len(regions) % 6) != 0 {
        return mc_fail(st, mc_bad_stride(), 0);
    }
    if (crate::port::cells_len(pages) % 16) != 0 {
        return mc_fail(st, mc_bad_stride(), 0);
    }
    if (crate::port::cells_len(ledger) % 10) != 0 {
        return mc_fail(st, mc_bad_stride(), 0);
    }
    if (crate::port::cells_len(layout) % 8) != 0 {
        return mc_fail(st, mc_bad_stride(), 0);
    }
    if nn < 1 {
        return mc_fail(st, mc_no_root(), 0);
    }
    if nget(nodes, 0, 0) != nk_document() {
        return mc_fail(st, mc_no_root(), 0);
    }
    if nget(nodes, 0, 1) != -1 {
        return mc_fail(st, mc_no_root(), 0);
    }
    while i < nn {
        rc = mc_check_node(nodes, attrs, regions, text, i, nn);
        if rc != 0 {
            return mc_fail(st, rc, i);
        }
        i += 1;
    }
    i = 0;
    while i < nn {
        kids = mc_check_children(nodes, i, nn);
        if kids < 0 {
            return mc_fail(st, mc_bad_tree(), i);
        }
        total += kids;
        if nget(nodes, i, 1) >= 0 {
            nonroot += 1;
        }
        i += 1;
    }
    if total != nonroot {
        return mc_fail(st, mc_bad_tree(), 0);
    }
    rc = mc_check_order(nodes, nn, st);
    if rc != 0 {
        return rc;
    }
    i = 0;
    while i < (crate::port::cells_len(pages) / 16) {
        if mc_run_ok(pget(pages, i, 1), pget(pages, i, 2), tl) == 0 {
            return mc_fail(st, mc_bad_page(), i);
        }
        i += 1;
    }
    i = 0;
    while i < (crate::port::cells_len(ledger) / 10) {
        if mc_run_ok(lget(ledger, i, 6), lget(ledger, i, 7), tl) == 0 {
            return mc_fail(st, mc_bad_ledger(), i);
        }
        if (lget(ledger, i, 8) < -1) || (lget(ledger, i, 8) > 1000) {
            return mc_fail(st, mc_bad_ledger(), i);
        }
        i += 1;
    }
    i = 0;
    while i < (crate::port::cells_len(pages) / 16) {
        if pget(pages, i, 12) < 0 {
            return mc_fail(st, mc_bad_layout(), i);
        }
        if pget(pages, i, 12) > 0 {
            if pget(pages, i, 11) < 0 {
                return mc_fail(st, mc_bad_layout(), i);
            }
            if pget(pages, i, 11) > (nlay - pget(pages, i, 12)) {
                return mc_fail(st, mc_bad_layout(), i);
            }
            j = 0;
            while j < pget(pages, i, 12) {
                if yget(layout, pget(pages, i, 11) + j, 0) != pget(pages, i, 0) {
                    return mc_fail(st, mc_bad_layout(), i);
                }
                if (yget(layout, pget(pages, i, 11) + j, 3) != rl_body()) && (yget(layout, pget(pages, i, 11) + j, 3) != rl_margin()) && (yget(layout, pget(pages, i, 11) + j, 3) != rl_sidebar()) {
                    return mc_fail(st, mc_bad_layout(), i);
                }
                j += 1;
            }
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn mh_fold(h: i64, c: &mut crate::port::Cells) -> i64 {
    // FNV-1a over the cells of one arena, each as a 32-bit pattern, then
    // the arena's length -- so two arenas that differ only in where one
    // ends and the next begins do not collide.
    let mut i: i32 = 0;
    let mut acc: i64 = h;
    while i < crate::port::cells_len(c) {
        acc = (acc ^ (crate::port::cells_at(c, i) as i64)).wrapping_mul(1099511628211);
        i += 1;
    }
    return (acc ^ (crate::port::cells_len(c) as i64)).wrapping_mul(1099511628211);
}
pub fn model_hash(nodes: &mut crate::port::Cells, attrs: &mut crate::port::Cells, regions: &mut crate::port::Cells, text: &mut crate::port::Cells, pages: &mut crate::port::Cells, ledger: &mut crate::port::Cells, layout: &mut crate::port::Cells) -> i64 {
    // A 64-bit fingerprint of the whole Model: the gate's proof that four
    // targets built the same seven arenas. FNV-1a, offset basis
    // 14695981039346656037 (as a signed value) and prime 1099511628211.
    let mut h: i64 = -3750763034362895579;
    h = mh_fold(h, nodes);
    h = mh_fold(h, attrs);
    h = mh_fold(h, regions);
    h = mh_fold(h, text);
    h = mh_fold(h, pages);
    h = mh_fold(h, ledger);
    h = mh_fold(h, layout);
    return h;
}
pub(crate) fn xget(assets: &mut crate::port::Cells, a: i32, f: i32) -> i32 {
    return crate::port::cells_at(assets, (a * 24) + f);
}
pub(crate) fn xset(mut assets: &mut crate::port::Cells, a: i32, f: i32, v: i32) -> i32 {
    crate::port::cells_set(assets, (a * 24) + f, v);
    return 0;
}
pub fn asset_add(mut assets: &mut crate::port::Cells, mtype: i32, origin: i32, afrom: i32, object: i32, bstart: i32, blen: i32, w: i32, h: i32, dpi: i32, flags: i32) -> i32 {
    // Append an asset (no uses yet, the hash zero) and answer its id. `object` is -1 for none, `dpi` 0.
    let id: i32 = crate::port::cells_len(assets) / 24;
    let mut i: i32 = 0;
    crate::port::cells_push(assets, mtype);
    crate::port::cells_push(assets, origin);
    crate::port::cells_push(assets, afrom);
    crate::port::cells_push(assets, object);
    crate::port::cells_push(assets, bstart);
    crate::port::cells_push(assets, blen);
    while i < 8 {
        crate::port::cells_push(assets, 0);
        i += 1;
    }
    crate::port::cells_push(assets, w);
    crate::port::cells_push(assets, h);
    crate::port::cells_push(assets, dpi);
    crate::port::cells_push(assets, flags);
    crate::port::cells_push(assets, -1);
    crate::port::cells_push(assets, 0);
    crate::port::cells_push(assets, -1);
    crate::port::cells_push(assets, 0);
    crate::port::cells_push(assets, 0);
    crate::port::cells_push(assets, 0);
    return id;
}
pub fn asset_set_sha(mut assets: &mut crate::port::Cells, a: i32, i: i32, v: i32) -> i32 {
    // Word i (0..7) of asset a's SHA-256.
    return xset(assets, a, 6 + i, v);
}
pub fn asset_set_flags(mut assets: &mut crate::port::Cells, a: i32, v: i32) -> i32 {
    return xset(assets, a, 17, v);
}
pub fn use_add(mut assets: &mut crate::port::Cells, mut uses: &mut crate::port::Cells, a: i32, node: i32, page: i32, x0: i32, y0: i32, x1: i32, y1: i32) -> i32 {
    // Append a use of asset a by `node`, at the page region given, to the END of the asset's chain; answers its index.
    let u: i32 = crate::port::cells_len(uses) / 8;
    let tail: i32 = xget(assets, a, 20);
    let cnt: i32 = xget(assets, a, 19);
    crate::port::cells_push(uses, a);
    crate::port::cells_push(uses, node);
    crate::port::cells_push(uses, page);
    crate::port::cells_push(uses, x0);
    crate::port::cells_push(uses, y0);
    crate::port::cells_push(uses, x1);
    crate::port::cells_push(uses, y1);
    crate::port::cells_push(uses, -1);
    if tail < 0 {
        xset(assets, a, 18, u);
    } else {
        crate::port::cells_set(uses, (tail * 8) + 7, u);
    }
    xset(assets, a, 20, u);
    xset(assets, a, 19, cnt + 1);
    return u;
}
pub fn asset_count(assets: &mut crate::port::Cells) -> i32 {
    return crate::port::cells_len(assets) / 24;
}
pub fn asset_type(assets: &mut crate::port::Cells, a: i32) -> i32 {
    return xget(assets, a, 0);
}
pub fn asset_origin(assets: &mut crate::port::Cells, a: i32) -> i32 {
    return xget(assets, a, 1);
}
pub fn asset_from(assets: &mut crate::port::Cells, a: i32) -> i32 {
    return xget(assets, a, 2);
}
pub fn asset_object(assets: &mut crate::port::Cells, a: i32) -> i32 {
    return xget(assets, a, 3);
}
pub fn asset_bstart(assets: &mut crate::port::Cells, a: i32) -> i32 {
    return xget(assets, a, 4);
}
pub fn asset_blen(assets: &mut crate::port::Cells, a: i32) -> i32 {
    return xget(assets, a, 5);
}
